Future<FaResult> runFaTrajectory(
  List<String> args, {
  String? sessionRoot,
}) async {
  final run = await Process.run(
    'dart',
    [
      'run',
      'bin/fah.dart',
      'trajectory',
      ...args,
      '--session-root',
      sessionRoot ?? sessionsRoot.path,
