    workingDirectory: Directory.current.path,
    environment: {'HOME': tempHome.path, 'OPENAI_API_KEY': 'mock'},
    stdoutEncoding: utf8,
    stderrEncoding: utf8,
  ).timeout(const Duration(minutes: 3));
  return FaResult(
    stdout: run.stdout as String,
    stderr: run.stderr as String,
    exitCode: run.exitCode,
  );
}

