```dart
/// gh-1300 FA_BIN seam ...
static (String, List<String>) resolveFaCommand({
  required List<String> args,
  String? executable,
  List<String>? executableArgs,
  String? ambientFaBin,
}) {
  final faBin = ambientFaBin ?? Platform.environment['FA_BIN'];
  if (faBin != null && faBin.isNotEmpty) return (faBin, args);
  return (executable ?? 'dart', executableArgs ?? ['bin/fah.dart', ...args]);
}
```

